package org.maxbot.core;
import java.util.*;
import org.maxbot.core.Geometry.*;
public final class AutonomyTest {
  private static void check(boolean value,String message){CoreTest.check(value,message);}
  static VehicleModel dynamics(){VehicleModel m=new VehicleModel();m.reviewed=true;m.revision=1;m.provenance=new String[]{"SYNTHETIC HOST FIXTURE, never deploy"};m.speedPwm=new double[][]{{0,0},{.1,120},{.5,200}};m.steeringRateRadS=2.;m.steeringLagS=.06;m.accelerationMps2=.3;m.brakingMps2=.5;m.lateralMps2=.3;m.vioLagS=.05;m.applicationDelayS=.02;m.validSpeedRangeMps=new double[]{0,.5};return m;}
  public static void run(){
    ClockSync clock=new ClockSync();check(clock.sample("a",1000,1015,1017,1012),"four timestamp sample");check(clock.toRemote(1012,1012)==1022,"NTP offset");check(clock.uncertaintyMs(1012)==6,"NTP uncertainty");check(!clock.sample("a",2000,2010,2011,2000),"negative network delay rejected");clock.sample("b",3000,15,17,3012);check(clock.toLocal(22)==3012,"boot reset clock");check(!Double.isFinite(clock.uncertaintyMs(10000)),"sync expires");
    SteeringTiming response=new SteeringTiming();response.sample(980,0);response.sent(1,10,true);response.applied(1,1000);response.sample(1020,.2);response.sample(1040,2);response.sample(1060,9);for(long t=1080;t<=1160;t+=20)response.sample(t,10);check(response.onset()[0]==40&&response.settling()[0]==60,"potentiometer onset/settling causal fixture");response.sent(2,-10,true);response.applied(2,1180);response.sample(1300,-10);check(response.censored()==1,"lost pot samples censor physical response estimate");
    CausalTiming timing=new CausalTiming();long base=1_000_000_000L;
    for(int i=1;i<=100;i++){timing.sent(i,base,base,base,base);timing.applied(i,base+i*1_000_000L,base+101_000_000L,true);}
    check(timing.samples()==100,"per-command samples");check(timing.imageAvailable()[1]==1,"old frame only first application");check(timing.policyApplied()[1]==95&&timing.policyApplied()[2]==99,"delayed causal percentiles");timing.sent(200,base,base,base,base);check(timing.pending()==1,"in-flight application is pending");timing.expire(base+501_000_000L);check(timing.missing()==1,"missing acknowledgement counted after its bound");timing.reset();check(Double.isNaN(timing.imageAvailable()[0]),"no data is unavailable");
    Calibration c=CoreTest.calibrated();RunSupervisor manual=new RunSupervisor(c,new SlalomPolicy(new SlalomPolicy.Parameters()));manual.link(true);manual.heartbeat(base);manual.telemetry(0,8,base,true,"");check(manual.manual(0,120,true,base,base+10_000_000L),"original deadline accepted");check(manual.tick(base+11_000_000L).pwm==0,"original manual event expires");check(!manual.manual(0,120,true,base+12_000_000L,base+10_000_000L),"new packet cannot revive old manual event");
    VehicleModel m=dynamics();SlalomPolicy policy=new SlalomPolicy(new SlalomPolicy.Parameters());policy.model(m);List<Trajectory.Sample> points=new ArrayList<>();for(int i=0;i<=100;i++){Trajectory.Sample s=new Trajectory.Sample(i*.02,0,0,0,i*.02);s.speed=.1;points.add(s);}Trajectory path=new Trajectory(points,20);
    RunSupervisor.Output out=policy.followAt(new Pose(0,0,0,0,base),0,path,0,c,base);check(out!=null&&out.steeringDeg==0&&out.pwm>0,"straight pure pursuit with measured feedforward");check(policy.followAt(new Pose(0,0,0,0,base),0,path,0,c,base+20_000_000L)!=null,"50 Hz control may consume repeated 30 Hz VIO");
    check(policy.followAt(new Pose(1,0,Math.PI,0,base+40_000_000L),0,path,50,c,base+40_000_000L)==null,"behind preview stops");
    Point center=Geometry.coneCenterFromRim(new Point(1,0),new Point(0,0),.1);check(Math.abs(center.x-1.1)<1e-9,"visible rim not metric center");double sensitivity=(9+.09924*.09924)/.09924*Math.toRadians(.5);check(sensitivity>.79&&sensitivity<.80,"low camera pitch sensitivity");
    CourseMap map=new CourseMap(new Pose(0,0,0,0,base));List<Point> cones=List.of(new Point(2,0),new Point(4,0),new Point(6,0),new Point(8,0));for(int i=1;i<=30;i++)map.observe(cones,i);boolean rejected=false;try{map.freeze();}catch(IllegalStateException e){rejected=true;}check(rejected,"residual scatter cannot certify empirical accuracy");map.approveGeometry(.01,2);map.freeze();
    ReferenceTrajectory r=new ReferenceTrajectory();r.schemaVersion=1;r.revision=1;r.referenceId="b".repeat(64);r.calibrationId=c.firmwareCalibrationId;r.geometryId=c.geometryId;r.mapEpoch="wrong";r.frameId=map.frameId();r.vehicleModelId="c".repeat(64);r.sides=new int[]{-1,1,-1,1};r.clearanceM=.15;r.samples=points;r.validator=new ReferenceTrajectory.Validator();r.validator.feasible=true;check(r.validate(c,m,map,"c".repeat(64)).contains("Map/frame identity mismatch"),"reference map epoch mismatch");
    StateEstimator estimator=new StateEstimator();estimator.vio(new Pose(0,0,0,.2,base));estimator.gyro(base,0,true);check(estimator.predict(base,base+20_000_000L,null,null)!=null,"bounded VIO/gyro propagation");check(estimator.predict(base+110_000_000L,base+120_000_000L,null,null)==null,"fresh images cannot renew stale VIO");
    double[] corrected=InertialTransform.axleAcceleration(new double[]{-.1,0,9.8},new double[]{0,0,9.8},new double[]{0,0,1},new double[]{0,0,0},new double[]{.1,0,0});check(Math.abs(corrected[0])<1e-9&&Math.abs(corrected[2])<1e-9,"gravity and centripetal lever-arm correction");
    ModelManifest manifest=new ModelManifest();manifest.schemaVersion=1;manifest.sha256="a".repeat(64);manifest.exporterVersion="fixture";manifest.family="yolov5n";manifest.classes=new String[]{"cone"};manifest.inputShape=new int[]{1,320,320,3};manifest.outputShape=new int[]{1,6300,6};manifest.inputType=manifest.outputType="FLOAT32";manifest.normalization="zero_to_one";manifest.orientation="sensor_cpu_unrotated_letterbox";manifest.decoder="yolov5_xywh_objectness";manifest.coordinates="normalized";manifest.nmsRequired=true;
    check(!manifest.liveValidated(),"tensor compatibility never approves real cone accuracy");
    ModelDecoder decoder=new ModelDecoder(manifest);float[] box=new float[5];check(decoder.decode(new float[]{.5f,.5f,.2f,.2f,1,.9f},640,480,box)&&Math.abs(box[0]-256)<.001&&Math.abs(box[1]-176)<.001,"YOLOv5 letterbox decoding");check(!decoder.decode(new float[6],640,480,box),"empty detections stay empty");
    manifest.family="yolo26n";manifest.decoder="end_to_end_xyxy_score_class";manifest.outputShape=new int[]{1,300,6};manifest.coordinates="input_pixels";manifest.nmsRequired=false;decoder=new ModelDecoder(manifest);check(decoder.decode(new float[]{128,128,192,192,.9f,0},640,480,box)&&Math.abs(box[0]-256)<.001&&Math.abs(box[1]-176)<.001,"explicit YOLO26 XYXY contract");check(!decoder.decode(new float[]{128,128,192,192,.9f,1},640,480,box),"unknown class rejected");manifest.orientation="guessed_rotation";check(!manifest.validate().isEmpty(),"unsupported rotation rejected");manifest.orientation="sensor_cpu_unrotated_letterbox";manifest.inputType="INT8";manifest.inputScale=0;check(!manifest.validate().isEmpty(),"missing quantization rejected");
    try{referenceAndStopFixtures();}catch(Exception e){throw new AssertionError(e);}
    String text=Protocol.motion("0123456789abcdef","a".repeat(32),3,42,1000,1080,"DRIVE",12000,120,"99","88","b".repeat(64));check(Protocol.sign("synthetic-contract-key-never-deploy",text).equals("5e5eb83e079bf6e90192527c7ccee3e3bb1ebbc1ea2d8d600d79d163dbf88d67"),"cross-language v2 canonical vector");
  }
  private static void referenceAndStopFixtures()throws Exception{
    Calibration c=CoreTest.calibrated();c.geometryId="b".repeat(64);c.car.wheelbaseM=.173;c.car.widthM=.144;c.car.frontOverhangM=.03894;c.car.rearOverhangM=.055;c.cones.baseDiameterM=.2;c.steering.leftDeg=26.;c.steering.rightDeg=-26.;c.steering.adc=new int[]{1158,785,461};c.steering.degrees=new double[]{-26,0,26};c.limits.finishClearM=3.;c.limits.lateralSpaceM=8.;c.limits.floorBoundsM=new double[]{-1,11,-4,4};
    long base=2_000_000_000L;Pose origin=new Pose(.4,-.2,.3,0,base);CourseMap map=new CourseMap(origin);List<Point> cones=new ArrayList<>();for(int i=0;i<4;i++)cones.add(Geometry.world(origin,2+2*i,0));for(int i=1;i<=30;i++)map.observe(cones,i);map.approveGeometry(.001,2);map.freeze();
    java.nio.file.Path root=java.nio.file.Path.of(System.getProperty("user.dir"));while(!java.nio.file.Files.exists(root.resolve("maxbot/config/fixtures/reference-nondeployable.csv")))root=root.getParent();
    ReferenceTrajectory ref=new ReferenceTrajectory();ref.schemaVersion=1;ref.revision=1;ref.referenceId="e".repeat(64);ref.frameId=map.frameId();ref.mapEpoch=map.mapEpoch();ref.calibrationId=c.firmwareCalibrationId;ref.geometryId=c.geometryId;ref.vehicleModelId="c".repeat(64);ref.sides=new int[]{-1,1,-1,1};ref.clearanceM=.15;ref.uncertaintyM=.001;ref.validator=new ReferenceTrajectory.Validator();ref.validator.feasible=true;ref.samples=new ArrayList<>();
    for(String line:java.nio.file.Files.readAllLines(root.resolve("maxbot/config/fixtures/reference-nondeployable.csv"))){
      if(line.startsWith("# finishS=")){ref.finishS=Double.parseDouble(line.substring(10));continue;}if(line.startsWith("#"))continue;
      String[] values=line.split(",");double[] v=java.util.Arrays.stream(values).mapToDouble(Double::parseDouble).toArray();Trajectory.Sample p=new Trajectory.Sample(v[0],v[1],v[2],v[3],v[4]);p.speed=v[5];ref.samples.add(p);
    }
    List<String> errors=ref.validate(c,dynamics(),map,"c".repeat(64));check(errors.isEmpty(),"Python golden reference independently validates in rotated Java frame: "+errors);
    PassageScorer scorer=new PassageScorer();Trajectory world=ref.trajectory(map);for(int i=0;i<world.samples.size();i++){Trajectory.Sample p=world.samples.get(i);check(scorer.update(new Pose(p.x,p.y,p.yaw,p.speed,base+i*50_000_000L),map,c,.001),"ordered swept passage: "+scorer.fault());}
    check(scorer.passed()==4&&scorer.finishNs()>base&&scorer.finishNs()<base+(world.samples.size()-1)*50_000_000L,"whole-body finish precedes rest");
    ref.samples.get(100).speed=Double.NaN;check(!ref.validate(c,dynamics(),map,"c".repeat(64)).isEmpty(),"nonfinite reference rejected");ref.samples.get(100).speed=.1;
    final java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);
    RunSupervisor.Controller slow=new RunSupervisor.Controller(){public boolean available(){return true;}public RunSupervisor.Output follow(Pose pose,double angle,Trajectory path,int index,Calibration calibration){entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return new RunSupervisor.Output("DRIVE",0,120);}};
    RunSupervisor supervisor=new RunSupervisor(c,slow);supervisor.vehicleModel(dynamics(),"c".repeat(64));supervisor.modelReady(true);supervisor.link(true);supervisor.localization(new Pose(0,0,0,0,base),true);supervisor.imu(base,0,true);supervisor.telemetry(0,8,base,true,"");supervisor.heartbeat(base);
    check(supervisor.startScout(base),"one-sided scout supports an occluded launch");
    java.util.concurrent.FutureTask<RunSupervisor.Output> tick=new java.util.concurrent.FutureTask<>(()->supervisor.tick(base));new Thread(tick,"slow-policy-fixture").start();
    check(entered.await(1,java.util.concurrent.TimeUnit.SECONDS),"slow policy entered");long before=System.nanoTime();supervisor.stop("Manual stop during slow worker");check(System.nanoTime()-before<50_000_000L,"stop does not wait for policy monitor");release.countDown();check(tick.get(1,java.util.concurrent.TimeUnit.SECONDS).pwm==0,"slow completed output cannot revive stopped epoch");
  }

}
